/*
 * A003144  Positions of letter a in the tribonacci word abacabaabacababac...
 *          generated by a->ab, b->ac, c->a (cf. A092782).
 * https://oeis.org/A003144
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   search; build the tribonacci word by self-expansion under a->ab,
 *            b->ac, c->a and record the positions of a (memoized)
 * Range:     u8 n <= 139, u16 n <= 9717, u32 n <= 9717, u64 n <= 9717,
 *            u128 n <= 9717, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static char *tw_w = NULL;
static size_t tw_len = 0, tw_cap = 0, tw_gen = 0;
static uint64_t *tw_pos = NULL;
static size_t tw_npos = 0, tw_pcap = 0;

static void tw_push(char c) {
    if (tw_len >= tw_cap) {
        size_t nc = tw_cap ? tw_cap * 2 : 1024;
        tw_w = (char *)realloc(tw_w, nc);
        tw_cap = nc;
    }
    tw_w[tw_len++] = c;
    if (c == 'a') {
        if (tw_npos >= tw_pcap) {
            size_t nc = tw_pcap ? tw_pcap * 2 : 1024;
            tw_pos = (uint64_t *)realloc(tw_pos, nc * sizeof(uint64_t));
            tw_pcap = nc;
        }
        tw_pos[tw_npos++] = (uint64_t)tw_len; /* 1-indexed position */
    }
}

seq_t a(idx_t n) {
    if (tw_len == 0) {
        tw_push('a');
        tw_push('b');
        tw_gen = 1;
    }
    while ((idx_t)tw_npos < n) {
        char c = tw_w[tw_gen++];
        if (c == 'a') {
            tw_push('a');
            tw_push('b');
        } else if (c == 'b') {
            tw_push('a');
            tw_push('c');
        } else {
            tw_push('a');
        }
    }
    return (seq_t)tw_pos[n - 1];
}
